// Generated by Claude/specs/courses-tools/sync-hr.js from Claude/specs/lxd-course-hr-pilot/out-rounds/hr-pilot-block.js. Do not hand-edit.
(function(E){ const x = E["hr-m7"] = E["hr-m7"] || {units:{}}; x.units["hr-7-3"] = {"explain":{"id":"c-hr-7-3-e","course":"hr","unit":"hr-7-3","type":"explain","level":"B1","title":{"en":"Absence and return to work","tr":"Devamsızlık ve işe dönüş","fa":"غیبت و بازگشت به کار"},"objective":{"en":"After this lesson, you can hold a return-to-work talk after an absence and write a short note of it.","tr":"Bu dersin sonunda bir devamsızlıktan sonra işe dönüş görüşmesi yapıp kısa bir notunu yazabileceksin.","fa":"بعد از این درس می‌توانی بعد از یک غیبت، گفتگوی بازگشت به کار انجام بدهی و یادداشت کوتاهی از آن بنویسی."},"hook":{"en":"Offer support first, then talk about any pattern. A return-to-work talk can find a cause that a warning would miss. Deniz is back after five days off. Omar wants a warning; Leyla wants a conversation first.","tr":"Önce destek ver, sonra tekrar eden durumu konuş. İşe dönüş görüşmesi, bir uyarının kaçıracağı bir nedeni bulabilir. Deniz beş günlük izinden döndü. Omar uyarı istiyor; Leyla önce bir konuşma istiyor.","fa":"اول حمایت کن و بعد درباره‌ی الگوی غیبت حرف بزن. گفتگوی بازگشت به کار می‌تواند دلیلی را پیدا کند که اخطار نمی‌بیند. دنیز بعد از پنج روز غیبت برگشته. عمر می‌خواهد تذکر بدهد؛ لیلا اول یک گفتگو می‌خواهد."},"before":{"en":"Write a short note of a return-to-work talk: how the person is, the cause you found, the change you agreed and the next check-in.","tr":"Bir işe dönüş görüşmesinin kısa notunu yaz: kişinin nasıl olduğu, bulduğun neden, anlaştığınız değişiklik ve bir sonraki görüşme.","fa":"یادداشت کوتاهی از یک گفتگوی بازگشت به کار بنویس: حال آن شخص، علتی که پیدا کردی، تغییری که توافق کردید و قرار بعدی."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"5"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Support first, pattern second","tr":"Önce destek, sonra tekrar eden durum","fa":"اول حمایت و بعد الگوی غیبت"},"body":{"en":"Welcome the person and ask how they are. If there is a pattern of absences, state it calmly, because the aim is support, not blame. Then look for anything at work you can change.","tr":"Kişiye hoş geldin de ve nasıl olduğunu sor. Tekrar eden devamsızlık varsa sakince söyle, çünkü amaç suçlamak değil, destek olmak. Sonra iş yerinde değiştirebileceğin bir şey ara.","fa":"به آن شخص خوشامد بگو و بپرس حالش چطور است. اگر غیبت‌ها الگویی دارند، آرام بگو، چون هدف حمایت است، نه سرزنش. بعد ببین در کار چه چیزی را می‌توانی تغییر بدهی."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Patterns up to now: the present perfect","tr":"Şimdiye kadarki örüntüler: present perfect","fa":"الگوهای تا امروز: حال کامل"},"steps":[{"en":"A pattern from a past point up to now: have/has + past participle.","tr":"Geçmişteki bir noktadan bugüne bir örüntü: have/has + past participle.","fa":"برای الگویی از یک زمان در گذشته تا امروز، have/has و اسم مفعول می‌آید.","ex":"You've been off three times since January."},{"en":"A finished day in the past: past simple.","tr":"Geçmişte bitmiş bir gün: past simple.","fa":"برای یک روز تمام‌شده در گذشته، گذشته‌ی ساده می‌آید.","ex":"You called in sick on Monday."},{"en":"Asking how someone is since they came back: How have you been?","tr":"Döndüğünden beri nasıl olduğunu sormak: How have you been?","fa":"پرسیدن حال کسی از وقتی برگشته: How have you been?","ex":"How have you been since Monday?"}],"table":{"headers":{"en":["Time word","Tense","Example"],"tr":["Zaman ifadesi","Zaman","Örnek"],"fa":["کلمه‌ی زمان","زمان دستوری","مثال"]},"rows":[["since January","present perfect","You've been off three times since January."],["this year","present perfect","It has happened twice this year."],["on Monday, last week","past simple","You came back last week."]]},"tip":{"en":"Turkish 'ocaktan beri üç kez izin aldın' and Persian «از ژانویه سه بار مرخصی گرفتی» use a past form; English needs the present perfect with since.","tr":"Türkçede 'ocaktan beri üç kez izin aldın' denir; İngilizcede since ile present perfect gerekir.","fa":"در فارسی می‌گوییم «از ژانویه سه بار مرخصی گرفتی»؛ انگلیسی با since حال کامل می‌خواهد."},"wrong":"You took leave three times since January.","right":"You have taken leave three times since January."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"Welcome back. How are you feeling?","meaning":{"en":"Opens the talk kindly.","tr":"Görüşmeyi nazikçe açar.","fa":"گفتگو را با مهربانی شروع می‌کند."}},{"phrase":"Is there anything we can do to help?","meaning":{"en":"Offers support or changes.","tr":"Destek ya da düzenleme önerir.","fa":"کمک یا تغییر در کار را پیشنهاد می‌کند."}},{"phrase":"Shall we check in again next Friday?","meaning":{"en":"Agrees a follow-up.","tr":"Bir takip görüşmesinde anlaşır.","fa":"برای جلسه‌ی پیگیری توافق می‌کند."}},{"phrase":"return-to-work talk","meaning":{"en":"A short, private meeting after an absence.","tr":"Devamsızlıktan sonra kısa, özel bir görüşme.","fa":"گفتگوی کوتاه و خصوصی بعد از غیبت."}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"A conversation before a warning","tr":"Uyarıdan önce konuşma","fa":"اول گفتگو، بعد تذکر"},"body":{"en":"Acas, the UK's workplace advice service, describes a return-to-work talk as a short, private, informal chat soon after the person is back. Welcome them, ask how they are, look for anything at work you can help with, and agree a plan. It is not a warning, and they do not have to share medical details.","tr":"Birleşik Krallık’ın iş yeri danışma kurumu Acas, işe dönüş görüşmesini kişi döndükten kısa süre sonra yapılan kısa, özel ve resmî olmayan bir sohbet olarak tanımlar. Kişiyi karşıla, nasıl olduğunu sor, iş yerinde yardım edebileceğin bir şey olup olmadığına bak ve bir plan üzerinde anlaş. Bu bir uyarı değildir ve kişi sağlık ayrıntılarını paylaşmak zorunda değildir.","fa":"در بریتانیا، Acas (مرکز مشاوره‌ی روابط کار) گفتگوی بازگشت به کار را یک گپ کوتاه، خصوصی و غیررسمی می‌داند که کمی بعد از برگشتن فرد انجام می‌شود. به او خوشامد بگو، حالش را بپرس، ببین در محیط کار چیزی هست که بتوانی در آن کمک کنی و سر یک برنامه توافق کن. این گفتگو تذکر نیست و او مجبور نیست جزئیات پزشکی‌اش را بگوید."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از سرزنش تا خوشامد و پیشنهاد کمک"},"text":"Facts: The person is back today. They have been off twice this year.","item":"You were off again. What's wrong this time?","why":{"en":"Weak: blame from the first line. Strong: welcome, fact, offer of help.","tr":"Zayıf: ilk cümleden suçlama. Güçlü: karşılama, olgu, yardım önerisi.","fa":"نسخه‌ی اول از جمله‌ی اول سرزنش می‌کند. نسخه‌ی دوم خوشامد می‌گوید، واقعیت را می‌گوید و پیشنهاد کمک می‌دهد."},"answer":"Welcome back. How are you feeling? You've been off twice this year. Is anything at work making it harder?","cut":["again","What's wrong this time?"],"cutHint":{"en":"Tap the words that sound like blame.","tr":"Suçlama gibi duyulan sözlere dokun.","fa":"روی کلمه‌هایی بزن که بوی مقصر دانستن می‌دهند."}},"quick":{"prompt":"In a return-to-work talk, the person does not want to talk about their illness. What do you do?","options":["Respect it: they do not have to share medical details","Insist: you need the full story","Give them a warning"],"correct":0,"why":{"en":"Respect it: a return-to-work talk is a short, informal chat, not a warning, and the person does not have to share medical details.","tr":"Buna saygı göster: İşe dönüş görüşmesi bir uyarı değil, kısa ve resmî olmayan bir sohbettir; kişi tıbbi ayrıntıları paylaşmak zorunda değildir.","fa":"به آن احترام بگذار: گفتگوی بازگشت به کار یک گپ کوتاه و غیررسمی است، نه اخطار، و آن شخص مجبور نیست جزئیات پزشکی‌اش را بگوید."},"point":4},"remember":{"en":"Since + a time up to now: have/has + past participle. Result of this lesson: you can hold a supportive return-to-work talk. You also have the note of it.","tr":"Since + bugüne uzanan bir zaman: have/has + past participle. Bu dersin sonucu: destekleyici bir işe dönüş görüşmesi yapabilirsin ve elinde görüşmenin notu olur.","fa":"بعد از since، زمانی می‌آید که تا امروز ادامه دارد؛ پس have/has و اسم مفعول می‌خواهد. حالا می‌توانی گفتگوی بازگشت به کار را حمایتگرانه انجام بدهی. یادداشتش هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Gentle suggestions: it might help to...","tr":"Nazik öneriler: it might help to...","fa":"پیشنهاد نرم: it might help to..."},"steps":[{"en":"Suggest without ordering: it might help to + verb.","tr":"Emretmeden öner: it might help to + fiil.","fa":"بدون دستور دادن پیشنهاد بده: it might help to و فعل ساده.","ex":"It might help to start a little later for two weeks."},{"en":"Ask for their idea: would it help if we + past?","tr":"Onun fikrini sor: would it help if we + geçmiş zaman?","fa":"نظر خودش را بپرس: would it help if we و فعل گذشته.","ex":"Would it help if we changed your route?"},{"en":"Make it shared: we could try...","tr":"Ortak hâle getir: we could try...","fa":"با «ما» مشترکش کن: we could try...","ex":"We could try lighter loads until your back is better."}],"body":{"en":"B2 track: in the talk and the note, use it might help to once.","tr":"B2 yolu: görüşmede ve notta it might help to yapısını bir kez kullan.","fa":"مسیر B2: در گفتگو و یادداشت یک بار it might help to به کار ببر."}},"source":{"en":"Based on Acas guidance on return-to-work meetings.","tr":"Acas’ın işe dönüş görüşmeleri rehberine dayanır.","fa":"بر پایه‌ی راهنمای Acas درباره‌ی گفتگوی بازگشت به کار."}},"story":{"id":"c-hr-7-3-s","course":"hr","unit":"hr-7-3","level":"B1","genre":"Workplace","title":{"en":"Welcome Back","tr":"Tekrar Hoş Geldin","fa":"خوش برگشتی"},"text":"Deniz came back on Monday after five days off with a bad back. By nine o'clock Omar was at Leyla's desk with a printout.\n\n\"He's been off three times since January. I want to give him a written warning.\"\n\n\"Let me talk to him first,\" Leyla said. \"Three short absences can mean many things.\"\n\nShe met Deniz in the small room by the canteen. \"Welcome back. How are you feeling?\"\n\n\"Better, thanks. My back is still a bit stiff.\" He looked at the table. \"I know I've been off a lot.\"\n\n\"This isn't a warning,\" Leyla said. \"It's a short return-to-work chat. Has anything at work made your back worse?\"\n\nDeniz hesitated. \"The new crates on Route 7. They're twenty-five kilos each, and I load them alone. All three times, it started after a heavy week.\"\n\nLeyla wrote it down. \"Then let's change that. For the next two weeks, Hasan will load the heavy crates on your route, and we'll ask the warehouse about a lifting trolley. Shall we check in again next Friday?\"\n\nBack at her desk, Leyla showed Omar her note. Omar read it twice. \"Twenty-five kilos,\" he said. \"Nobody told me that.\"\n\n\"Nobody asked,\" said Leyla.","vocab":[{"word":"stiff","en":"Hard to move, a little painful.","tr":"tutulmuş, kaskatı","fa":"خشک و گرفته"},{"word":"printout","en":"A page printed from a computer.","tr":"çıktı","fa":"برگه‌ی چاپی"},{"word":"crate","en":"A large box for carrying goods.","tr":"kasa, sandık","fa":"جعبه‌ی بزرگ حمل بار"},{"word":"trolley","en":"A small cart on wheels for moving things.","tr":"el arabası","fa":"چرخ دستی"}],"quiz":[{"prompt":"What did Omar want to do?","options":["Give Deniz a written warning","Change Deniz's route","Give Deniz a week off"],"correct":0},{"prompt":"Which sentence describes a pattern up to now?","options":["Deniz came back on Monday.","He's been off three times since January.","He looked at the table."],"correct":1},{"prompt":"What did the talk find?","options":["A work cause the company can fix: heavy crates loaded alone","That Deniz does not like his job","Nothing new"],"correct":0},{"prompt":"Why does Omar read the note twice?","options":["He realises the absences had a cause at work","He is looking for spelling mistakes","He wants to sign it"],"correct":0}],"notice":{"en":"Notice how Leyla opens the talk before she asks any question about the absences.","tr":"Leyla’nın devamsızlıkla ilgili herhangi bir soru sormadan önce görüşmeyi nasıl açtığına dikkat et.","fa":"دقت کن لیلا قبل از هر سؤالی درباره‌ی غیبت‌ها، گفتگو را چطور شروع می‌کند."},"bridge":{"en":"Next: hold the return-to-work talk yourself.","tr":"Sırada: işe dönüş görüşmesini sen yap.","fa":"قدم بعد: گفتگوی بازگشت به کار را خودت انجام بده."}},"speaking":{"id":"hr-7-3","course":"hr","unit":"hr-7-3","rounds":[90,60],"topic":{"en":"Welcoming Someone Back After an Absence","tr":"Devamsızlıktan Sonra Birini Karşılamak","fa":"خوشامد گفتن به کسی بعد از غیبت"},"warmup":{"en":"When you came back to work or school after being ill, what did you want people to say?","tr":"Hastalıktan sonra işe ya da okula döndüğünde insanların ne demesini istedin?","fa":"وقتی بعد از بیماری به کار یا مدرسه برگشتی، دوست داشتی دیگران چه بگویند؟"},"questions":[{"en":"Welcome the person back and say what the talk is for.","tr":"Kişiyi karşıla ve görüşmenin ne için olduğunu söyle.","fa":"به فرد خوشامد بگو و بگو این گفتگو برای چیست."},{"en":"Ask how they are and whether anything at work made it worse.","tr":"Nasıl olduğunu ve iş yerinde durumu kötüleştiren bir şey olup olmadığını sor.","fa":"حالش را بپرس و ببین چیزی در کار اوضاع را بدتر کرده یا نه."},{"en":"Mention the pattern calmly, with the present perfect.","tr":"Örüntüden present perfect ile sakin bir şekilde bahset.","fa":"الگو را آرام و با حال کامل مطرح کن."},{"en":"Agree one change and a date to check in.","tr":"Bir değişiklikte ve bir takip tarihinde anlaş.","fa":"روی یک تغییر و یک تاریخ پیگیری توافق کن."}],"followups":[{"en":"Say it in 90 seconds, then in 60. Keep the welcome and the date.","tr":"Önce 90, sonra 60 saniyede söyle. Karşılamayı ve tarihi koru.","fa":"یک بار در ۹۰ ثانیه و بعد در ۶۰ ثانیه بگو. خوشامد و تاریخ را نگه دار."},{"en":"Now start a return-to-work chat with a colleague at your own workplace, in three sentences.","tr":"Şimdi kendi iş yerinde bir iş arkadaşınla işe dönüş görüşmesini üç cümleyle başlat.","fa":"حالا در سه جمله گفتگوی بازگشت به کار را با یکی از همکارانت در محل کار خودت شروع کن."}],"expressions":[{"phrase":"Welcome back. How are you feeling?","meaning":{"en":"A kind opening.","tr":"Nazik bir açılış.","fa":"شروعی مهربان."}},{"phrase":"You've been off three times since January.","meaning":{"en":"States the pattern as a fact.","tr":"Örüntüyü bir olgu olarak söyler.","fa":"الگو را به‌عنوان یک واقعیت می‌گوید."}},{"phrase":"Shall we check in again next Friday?","meaning":{"en":"Agrees a follow-up.","tr":"Bir takip görüşmesinde anlaşır.","fa":"برای پیگیری توافق می‌کند."}}],"culture":{"en":"Hold the talk in private, soon after the return, and keep medical details to what the person wants to share. The goal is support and a plan, not a punishment.","tr":"Görüşmeyi özel bir yerde, dönüşten kısa süre sonra yap ve sağlık ayrıntılarını kişinin paylaşmak istediği kadarla sınırla. Amaç ceza değil, destek ve bir plan.","fa":"گفتگو را خصوصی و کمی بعد از برگشتن انجام بده و از جزئیات پزشکی فقط تا جایی حرف بزن که خود فرد می‌خواهد. هدف حمایت و برنامه است، نه تنبیه."},"model":"Welcome back, Deniz. How are you feeling? This is just a short return-to-work chat, not a warning. You've been off three times since January, so I'd like to understand if anything at work is making it worse. Okay, the heavy crates. For two weeks Hasan will load them on your route. Shall we check in again next Friday?","selfCheck":[{"en":"I welcomed the person and said what the talk was for.","tr":"Kişiyi karşıladım ve görüşmenin amacını söyledim.","fa":"به فرد خوشامد گفتم و گفتم گفتگو برای چیست."},{"en":"I named the pattern with the present perfect.","tr":"Örüntüyü present perfect ile söyledim.","fa":"الگو را با حال کامل گفتم."},{"en":"I asked about causes at work.","tr":"İş yerindeki nedenleri sordum.","fa":"درباره‌ی علت‌های محیط کار پرسیدم."},{"en":"I agreed one change and a date.","tr":"Bir değişiklikte ve bir tarihte anlaştım.","fa":"روی یک تغییر و یک تاریخ توافق کردم."}]},"branch":{"id":"c-hr-7-3-b","course":"hr","unit":"hr-7-3","type":"branch","title":{"en":"The Return-to-Work Talk","tr":"İşe Dönüş Görüşmesi","fa":"گفتگوی بازگشت به کار"},"setting":{"en":"A small private room by the canteen. You are Leyla. Deniz is back after five days off with a bad back. Choose what to say. If a choice goes badly, you will see what happens and can try again.","tr":"Kantinin yanında küçük, özel bir oda. Sen Leyla’sın. Deniz sırt ağrısı yüzünden beş gün izin aldıktan sonra döndü. Ne söyleyeceğini seç. Bir seçim kötü giderse ne olduğunu görürsün ve yeniden deneyebilirsin.","fa":"یک اتاق کوچک و خصوصی کنار سلف. تو لیلا هستی. دنیز بعد از پنج روز غیبت به خاطر کمردرد برگشته. انتخاب کن چه بگویی. اگر انتخابی خوب پیش نرود، نتیجه‌اش را می‌بینی و می‌توانی دوباره امتحان کنی."},"start":"n1","nodes":{"n1":{"speaker":"Deniz","line":"Morning. Omar said you wanted to see me?","choices":[{"text":"Welcome back, Deniz. How are you feeling? This is just a short return-to-work chat.","tone":"good","next":"n2","reply":"Thanks. Better, I think.","feedback":{"en":"Warm, and you say what the meeting is. He can relax.","tr":"Sıcak ve görüşmenin ne olduğunu söylüyorsun. Rahatlayabilir.","fa":"گرم است و می‌گویی جلسه برای چیست. او می‌تواند آرام شود."}},{"text":"Yes. Five days off. That's a lot, isn't it?","tone":"poor","next":"n1","reply":"(Deniz crosses his arms.) I was ill.","feedback":{"en":"Starting with the number sounds like blame. Welcome him back first.","tr":"Sayıyla başlamak suçlama gibi duyulur. Önce onu karşıla.","fa":"شروع کردن با عدد مثل سرزنش است. اول به او خوشامد بگو."}},{"text":"Yes, I need to fill in a form about your absence.","tone":"ok","next":"n2","reply":"Okay... what do you need?","feedback":{"en":"Clear purpose, but cold. A short welcome would help.","tr":"Amaç net ama soğuk. Kısa bir karşılama iyi olurdu.","fa":"هدف روشن است ولی سرد. یک خوشامد کوتاه کمک می‌کرد."}}]},"n2":{"speaker":"Deniz","line":"My back is still a bit stiff, to be honest.","choices":[{"text":"I'm sorry to hear that. Has anything at work made it worse?","tone":"good","next":"n3","reply":"Well... the new crates on Route 7. I load them alone.","feedback":{"en":"An open question about work finds the real cause.","tr":"İşle ilgili açık bir soru gerçek nedeni buluyor.","fa":"یک سؤال باز درباره‌ی کار علت واقعی را پیدا می‌کند."}},{"text":"Lots of drivers have bad backs. You'll be fine.","tone":"poor","next":"n2","reply":"(He stops talking.) Right.","feedback":{"en":"This closes the topic. Ask about his work instead.","tr":"Bu, konuyu kapatıyor. Onun yerine işini sor.","fa":"این موضوع را می‌بندد. به‌جایش درباره‌ی کارش بپرس."}},{"text":"Okay. Can you drive full shifts today?","tone":"ok","next":"n3","reply":"Yes. But lifting the big crates is the hard part.","feedback":{"en":"Practical, but you jump ahead. He tells you the cause anyway.","tr":"Pratik ama aceleci. Yine de nedeni söylüyor.","fa":"عملی است، اما زود جلو می‌پری. با این حال علت را می‌گوید."}}]},"n3":{"speaker":"Deniz","line":"They're twenty-five kilos each. All three times, it started after a heavy week.","choices":[{"text":"Then for the next two weeks Hasan will load the heavy crates on your route. Shall we check in again next Friday?","tone":"good","next":"end","reply":"That would really help. Friday is fine.","feedback":{"en":"A clear change, a time limit and a follow-up date.","tr":"Net bir değişiklik, bir süre ve bir takip tarihi.","fa":"یک تغییر روشن، یک مدت مشخص و تاریخ پیگیری."}},{"text":"Sorry, lifting is part of the job.","tone":"poor","next":"n3","reply":"(Deniz sighs.) Then it will happen again.","feedback":{"en":"He just gave you a cause you can fix. Offer a change.","tr":"Sana çözebileceğin bir neden verdi. Bir değişiklik öner.","fa":"همین الان علتی گفت که می‌شود درستش کرد. یک تغییر پیشنهاد بده."}},{"text":"I'll mention it to Omar.","tone":"ok","next":"end","reply":"Okay. Thanks.","feedback":{"en":"It moves on, but Deniz leaves with no plan and no date.","tr":"Konuşma ilerliyor ama Deniz plansız ve tarihsiz çıkıyor.","fa":"جلو می‌رود، اما دنیز بدون برنامه و تاریخ بیرون می‌رود."}}]},"end":{"end":true,"outcome":{"en":"Deniz goes back to work with a plan. The absences had a cause at work, and now it is being fixed.","tr":"Deniz bir planla işe dönüyor. Devamsızlıkların iş yerinde bir nedeni vardı ve şimdi bu sorun çözülüyor.","fa":"دنیز با یک برنامه سر کار برمی‌گردد. غیبت‌ها علتی در محیط کار داشتند و حالا آن علت دارد برطرف می‌شود."}}}},"writing":{"id":"c-hr-7-3-w","course":"hr","unit":"hr-7-3","type":"writing","title":{"en":"The return-to-work note","tr":"İşe dönüş notu","fa":"یادداشت بازگشت به کار"},"difficulty":"medium","prompt":{"en":"Write the note of the talk (45-70 words): the date, how the person is, the cause you found, the change you agreed and the check-in date.","tr":"Görüşmenin notunu yaz (45-70 kelime): tarih, kişinin durumu, bulduğunuz neden, anlaştığınız değişiklik ve takip tarihi.","fa":"یادداشت گفتگو را بنویس (۴۵ تا ۷۰ کلمه): تاریخ، حال فرد، علتی که با هم پیدا کردید، تغییری که روی آن توافق کردید و تاریخ پیگیری."},"model":"Return-to-work talk, Monday 12 May. Deniz is feeling better but his back is still stiff. He has been off three times since January, each time after loading 25-kilo crates alone on Route 7. Agreed: for two weeks Hasan will load the heavy crates on this route, and we will ask the warehouse about a trolley. Check-in: Friday 23 May.","frame":"Return-to-work talk, ___. ___ is feeling ___. He has been off ___ since ___, each time ___. Agreed: for ___, ___. Check-in: ___.","words":[{"word":"since"},{"word":"agreed"},{"word":"check-in"}],"minWords":45,"minSentences":4,"rubric":["Task done: date, how they are, cause, change, check-in","Organised: facts first, then the agreement and the date","Language: present perfect with since for the pattern","Tone: factual, kind, no blame"],"rubricI18n":{"tr":["Görev: tarih, durum, neden, değişiklik, takip","Düzen: önce olgular, sonra anlaşma ve tarih","Dil: örüntü için since ile present perfect","Üslup: olgulara dayalı, nazik, suçlamasız"],"fa":["کامل بودن کار: تاریخ، حال فرد، علت، تغییر، پیگیری","نظم: اول واقعیت‌ها، بعد توافق و تاریخ","زبان: حال کامل با since برای الگو","لحن: بر پایه‌ی واقعیت، مهربان، بدون سرزنش"]},"portfolio":null,"parts":[{"t":{"en":"The date","tr":"Tarih","fa":"تاریخ"},"find":["monday","may"],"sample":"Monday 12 May"},{"t":{"en":"How he is","tr":"Nasıl olduğu","fa":"حالش"},"find":["feeling better","is feeling"],"sample":"feeling better; his back is still stiff"},{"t":{"en":"The cause you found","tr":"Bulduğun neden","fa":"علتی که پیدا کردی"},"find":["since january","each time","has been off"],"sample":"off three times since January, after loading heavy crates alone"},{"t":{"en":"The change you agreed","tr":"Anlaştığınız değişiklik","fa":"تغییری که توافق کردید"},"find":["agreed","will load"],"sample":"Hasan loads the heavy crates for two weeks; ask about a trolley"},{"t":{"en":"The check-in date","tr":"Yeniden görüşme tarihi","fa":"تاریخ قرار بعدی"},"find":["check-in","check in"],"sample":"Friday 23 May"}]},"perspective":{"id":"c-hr-7-3-p","course":"hr","unit":"hr-7-3","type":"perspective","title":{"en":"Through Omar's eyes","tr":"Omar’ın gözünden","fa":"از نگاه عمر"},"minSentences":2,"prompt":{"en":"You are Omar. You wanted to give Deniz a warning, and then you read Leyla's note. Write 2 sentences in first person: what did you not know, and what will you check next time?","tr":"Sen Omar’sın. Deniz’e uyarı vermek istiyordun, sonra Leyla’nın notunu okudun. Birinci tekil şahısla 2 cümle yaz: neyi bilmiyordun ve bir dahaki sefere neyi kontrol edeceksin?","fa":"تو عمر هستی. می‌خواستی به دنیز تذکر بدهی و بعد یادداشت لیلا را خواندی. از زبان خودت دو جمله بنویس: چه چیزی را نمی‌دانستی و دفعه‌ی بعد چه چیزی را بررسی می‌کنی؟"}},"exit":{"id":"c-hr-7-3-x","course":"hr","unit":"hr-7-3","type":"exit","items":[{"from":"hr-7-3","kind":"blank","point":2,"prompt":"She ___ off twice since March.","options":["has been","was","is"],"correct":0,"why":{"en":"has been: 'since March' runs until now, so the present perfect. 'Was' is for finished time, and 'is' doesn't go with since.","tr":"has been: 'since March' bugüne kadar sürer, bu yüzden present perfect. 'Was' bitmiş zaman içindir; 'is' since ile kullanılmaz.","fa":"has been درست است، چون since March تا الان ادامه دارد و حال کامل می‌خواهد. was برای زمان تمام‌شده است و is با since نمی‌آید."},"hint2":{"en":"since March shows a pattern that runs up to now. Which tense joins the past to now?","tr":"since March şimdiye kadar süren bir örüntüyü gösterir. Geçmişi şimdiye hangi zaman bağlar?","fa":"⁨since March⁩ الگویی را نشان می‌دهد که تا الان ادامه دارد. کدام زمان گذشته را به حالا وصل می‌کند؟"}},{"from":"hr-7-3","kind":"blank","point":2,"prompt":"How ___ you been since your operation?","options":["have","did","are"],"correct":0,"why":{"en":"have: 'How have you been since...' is the present perfect: the time runs until now. 'Did' and 'are' don't fit 'been'.","tr":"have: 'How have you been since...' present perfect'tir: süre bugüne kadar uzanır. 'Did' ve 'are' 'been' ile uymaz.","fa":"have درست است، چون How have you been since حال کامل است و زمان تا الان ادامه دارد. did و are با been جور نیستند."},"hint2":{"en":"been and since tell you this is the present perfect. Which helping verb does it use with you?","tr":"been ve since bunun present perfect olduğunu gösterir. you ile hangi yardımcı fiil kullanılır?","fa":"⁨been⁩ و ⁨since⁩ نشان می‌دهند که این زمان حال کامل است. با ⁨you⁩ کدام فعل کمکی می‌آید؟"}},{"from":"hr-7-3","kind":"mcq","point":1,"prompt":"What should come first in a return-to-work talk?","options":["A welcome and how the person is","The number of days missed","A written warning"],"correct":0,"why":{"en":"A welcome and how the person is: support first, then the pattern. Starting with days missed or a warning puts them on the defensive.","tr":"Hoş geldin demek ve kişinin nasıl olduğunu sormak: önce destek, sonra örüntü. Kaçırılan günlerle ya da uyarıyla başlamak kişiyi savunmaya geçirir.","fa":"خوشامد و پرسیدن حالش؛ اول حمایت و بعد الگوی غیبت. شروع با تعداد روزهای غیبت یا اخطار طرف را به حالت دفاعی می‌برد."}},{"from":"hr-7-2","kind":"blank","prompt":"He asked ___ he could have a copy of the notes.","options":["whether","that","what"],"correct":0,"point":2,"why":{"en":"whether: a reported yes/no question uses whether (or if). 'That' reports a statement, and 'what' needs a missing thing.","tr":"whether: aktarılan evet/hayır sorusu whether (ya da if) kullanır. 'That' bir bildirimi aktarır; 'what' eksik bir şey ister.","fa":"whether درست است، چون برای نقل سؤال بله‌یا‌نه whether یا if می‌آید. that جمله‌ی خبری را نقل می‌کند و what دنبال چیزی است که جمله ندارد."},"hint2":{"en":"The original was a yes/no question (Can I have a copy?). Which word reports a yes/no question?","tr":"Asıl soru bir evet/hayır sorusuydu (Can I have a copy?). Evet/hayır sorusu hangi kelimeyle aktarılır?","fa":"سؤال اصلی بله/نه بود (⁨Can I have a copy?).⁩ سؤال بله/نه با کدام کلمه نقل می‌شود؟"}},{"from":"hr-6-4","kind":"mcq","prompt":"Which exit-interview question is open?","options":["Did you like your team?","Was it the distance?","What did you enjoy most about working here?"],"correct":2,"point":2,"why":{"en":"'What did you enjoy most about working here?' is open: it can't be answered with yes or no. The other two invite only yes or no.","tr":"'What did you enjoy most about working here?' açık uçludur: evet ya da hayırla cevaplanamaz. Diğer ikisi yalnızca evet ya da hayır cevabına davet eder.","fa":"«What did you enjoy most about working here?» باز است و با بله یا نه جواب داده نمی‌شود. دو سؤال دیگر فقط بله یا نه می‌خواهند."}},{"from":"hr-5-2","kind":"mcq","prompt":"Which feedback has a situation, a behaviour and an impact?","options":["You are careless.","Great job last week!","On Tuesday you sent the report late, so the client meeting was moved."],"correct":2,"point":1,"why":{"en":"It names the situation (Tuesday), the behaviour (sent late) and the impact (meeting moved). 'You are careless' judges the person, and 'Great job!' gives no detail.","tr":"Durumu (salı), davranışı (geç gönderildi) ve etkiyi (toplantı ertelendi) söyler. 'You are careless' kişiyi yargılar; 'Great job!' ayrıntı vermez.","fa":"موقعیت (سه‌شنبه)، رفتار (دیر فرستادن) و اثر (عقب افتادن جلسه) را می‌گوید. You are careless آدم را قضاوت می‌کند و Great job! جزئیاتی ندارد."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
